    "All time" : "Semper",
    "_Last %n day_::_Last %n days_" : ["Ùrtima %n die","Ùrtimas %n dies"],
    "Posts of your own" : "Cummentos tuos",
    "Replies you wrote" : "Rispostas chi as iscritu",
